    "con_stock": false,
    "destacado": true,
    "sort_by": "precio_base",
    "order": "asc",
    "per_page": 16
};

fetch(url, {
    method: "GET",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

