body.append('proveedor_nombre_comercial', 'y');
body.append('proveedor_email', 'justina.gaylord@example.org');
body.append('proveedor_telefono', 'ikhwaykcmyuwpwlv');
body.append('proveedor_celular', 'qwrsitcpscqldzsn');
body.append('cuenta_bancaria_alias', 'r');
body.append('cuenta_bancaria_banco_clave', 'wtujwv');
body.append('cuenta_bancaria_banco_nombre', 'l');
body.append('cuenta_bancaria_tipo_cuenta', 'x');
body.append('cuenta_bancaria_campo_dependiente', 'j');
body.append('cuenta_bancaria_titular_cuenta', 'k');
body.append('cuenta_bancaria_referencia', 'l');
body.append('cuenta_bancaria_sucursal', 'q');
body.append('cuenta_bancaria_swift', 'p');
body.append('empresa', 'p');
body.append('usuario_id', '16');
