</p>



<span id="example-requests-POSTapi-proveedores--proveedor_id--solicitudes-pago">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost:80/api/proveedores/1/solicitudes-pago" \
    --header "Content-Type: multipart/form-data" \
    --header "Accept: application/json" \
    --form "descripcion_concepto=b"\
    --form "proveedor_id=architecto"\
    --form "empresa=n"\
    --form "usuario_id=16"\
    --form "usuario_nombre=n"\
    --form "residente=g"\
    --form "cotizacion_id=16"\
    --form "monto_total=39"\
    --form "observaciones=g"\
    --form "cuentas_bancarias[][cuenta_bancaria_id]=16"\
    --form "cuentas_bancarias[][datos_especificos][alias]=n"\
    --form "cuentas_bancarias[][datos_especificos][banco_clave]=gzmiyv"\
    --form "cuentas_bancarias[][datos_especificos][banco_nombre]=d"\
    --form "cuentas_bancarias[][datos_especificos][tipo_cuenta]=l"\
    --form "cuentas_bancarias[][datos_especificos][campo_dependiente]=j"\
    --form "cuentas_bancarias[][datos_especificos][titular_cuenta]=n"\
    --form "cuentas_bancarias[][datos_especificos][referencia]=i"\
    --form "cuentas_bancarias[][datos_especificos][estatus]=1"\
    --form "cuentas_bancarias[][datos_especificos][sucursal]=h"\
    --form "cuentas_bancarias[][datos_especificos][swift]=w"\
    --form "cuentas_bancarias[][datos_especificos][preferida]=1"\
    --form "factura_pdf=@C:\Users\PC\AppData\Local\Temp\phpDDDC.tmp" \
    --form "factura_xml=@C:\Users\PC\AppData\Local\Temp\phpDDDD.tmp" \
    --form "cotizacion=@C:\Users\PC\AppData\Local\Temp\phpDDDE.tmp" </code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:80/api/proveedores/1/solicitudes-pago"
);

const headers = {
    "Content-Type": "multipart/form-data",
    "Accept": "application/json",
};

const body = new FormData();
body.append('descripcion_concepto', 'b');
body.append('proveedor_id', 'architecto');
body.append('empresa', 'n');
body.append('usuario_id', '16');
body.append('usuario_nombre', 'n');
body.append('residente', 'g');
body.append('cotizacion_id', '16');
body.append('monto_total', '39');
body.append('observaciones', 'g');
body.append('cuentas_bancarias[][cuenta_bancaria_id]', '16');
body.append('cuentas_bancarias[][datos_especificos][alias]', 'n');
body.append('cuentas_bancarias[][datos_especificos][banco_clave]', 'gzmiyv');
body.append('cuentas_bancarias[][datos_especificos][banco_nombre]', 'd');
body.append('cuentas_bancarias[][datos_especificos][tipo_cuenta]', 'l');
body.append('cuentas_bancarias[][datos_especificos][campo_dependiente]', 'j');
body.append('cuentas_bancarias[][datos_especificos][titular_cuenta]', 'n');
body.append('cuentas_bancarias[][datos_especificos][referencia]', 'i');
body.append('cuentas_bancarias[][datos_especificos][estatus]', '1');
body.append('cuentas_bancarias[][datos_especificos][sucursal]', 'h');
body.append('cuentas_bancarias[][datos_especificos][swift]', 'w');
body.append('cuentas_bancarias[][datos_especificos][preferida]', '1');
body.append('factura_pdf', document.querySelector('input[name="factura_pdf"]').files[0]);
body.append('factura_xml', document.querySelector('input[name="factura_xml"]').files[0]);
body.append('cotizacion', document.querySelector('input[name="cotizacion"]').files[0]);

fetch(url, {
    method: "POST",
    headers,
    body,
}).then(response =&gt; response.json());</code></pre></div>

